svg.script:
function openEmbedded(url) {
  // Open a completely separate about:blank tab
  const newTab = window.open("about:blank", "_blank");

  if (!newTab) {
    alert("Popup was blocked. Please allow popups for this page.");
    return;
  }

  // Build the new about:blank page
  newTab.document.open();

  newTab.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <title>Embedded Page</title>

      <style>
        * {
          box-sizing: border-box;
        }

        html,
        body {
          margin: 0;
          padding: 0;
          width: 100%;
          height: 100%;
          overflow: hidden;
          background: #000;
        }

        iframe {
          display: block;
          width: 100%;
          height: 100%;
          border: 0;
        }
      </style>
    </head>

    <body>
      <iframe
        src="${url}"
        frameborder="0"
        allowfullscreen>
      </iframe>
    </body>
    </html>
  `);

  newTab.document.close();
}

